<?php
declare(strict_types=1);
namespace App\Interface\Http\Catalog;
use App\Application\Catalog\Mapper\PositionResponseMapper;use App\Application\Catalog\Mapper\SyllabusResponseMapper;use App\Application\Catalog\Service\CreatePositionService;use App\Application\Catalog\Service\CreateSyllabusService;use App\Application\Catalog\Service\ListPositionsService;use App\Application\Catalog\Service\ListSyllabiService;use App\Application\Identity\Service\AuthService;use App\Infrastructure\Http\ApiResponseFactory;use App\Infrastructure\Persistence\Doctrine\DoctrineEntityManagerFactory;use App\Infrastructure\Persistence\Doctrine\DoctrineTransactionManager;use App\Infrastructure\Persistence\Doctrine\Catalog\DoctrineExamRepository;use App\Infrastructure\Persistence\Doctrine\Catalog\DoctrinePositionRepository;use App\Infrastructure\Persistence\Doctrine\Catalog\DoctrineSyllabusRepository;use App\Interface\Http\Catalog\Controller\PositionSyllabusController;use App\Interface\Http\Identity\IdentityRequestFactory;use InvalidArgumentException;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;use Slim\App;
final class CatalogRouteRegistrar{public function __construct(private readonly ApiResponseFactory $responses,private readonly AuthService $auth){}public function register(App $app):void{$em=DoctrineEntityManagerFactory::create();$positions=new DoctrinePositionRepository($em);$syllabi=new DoctrineSyllabusRepository($em);$c=new PositionSyllabusController($this->auth,new CreatePositionService(new DoctrineExamRepository($em),$positions,new PositionResponseMapper(),new DoctrineTransactionManager($em)),new ListPositionsService($positions,new PositionResponseMapper()),new CreateSyllabusService($positions,$syllabi,new SyllabusResponseMapper(),new DoctrineTransactionManager($em)),new ListSyllabiService($syllabi,new SyllabusResponseMapper()),$this->responses);$f=new PositionSyllabusRequestFactory();$i=new IdentityRequestFactory();$r=$this->responses;$app->get('/v1/exams/{examId}/positions',static fn(ServerRequestInterface $q,ResponseInterface $p,array $a):ResponseInterface=>$c->listPositions($q,$p,$i->accessToken($q),(string)$a['examId']));$app->post('/v1/exams/{examId}/positions',static function(ServerRequestInterface $q,ResponseInterface $p,array $a)use($c,$f,$i,$r):ResponseInterface{try{return $c->createPosition($q,$p,$i->accessToken($q),$f->position($q,(string)$a['examId']));}catch(InvalidArgumentException $e){return $r->problem($p,'VALIDATION_FAILED','Um ou mais campos sao invalidos.',422,(string)$q->getAttribute('request_id'));}});$app->get('/v1/positions/{positionId}/syllabi',static fn(ServerRequestInterface $q,ResponseInterface $p,array $a):ResponseInterface=>$c->listSyllabi($q,$p,$i->accessToken($q),(string)$a['positionId']));$app->post('/v1/positions/{positionId}/syllabi',static function(ServerRequestInterface $q,ResponseInterface $p,array $a)use($c,$f,$i,$r):ResponseInterface{try{return $c->createSyllabus($q,$p,$i->accessToken($q),$f->syllabus($q,(string)$a['positionId']));}catch(InvalidArgumentException $e){return $r->problem($p,'VALIDATION_FAILED','Um ou mais campos sao invalidos.',422,(string)$q->getAttribute('request_id'));}});}}
